examples.code:
Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
    MonarchCalloutBlock(
        text = "Drafts are visible only to you.",
        tone = MonarchTone.Neutral,
    )
    MonarchCalloutBlock(
        text = "The import keeps existing labels.",
        tone = MonarchTone.Info,
    )
    MonarchCalloutBlock(
        text = "The checklist is complete.",
        tone = MonarchTone.Success,
    )
    MonarchCalloutBlock(
        text = "Archive the old project before you start.",
        tone = MonarchTone.Warning,
    )
    MonarchCalloutBlock(
        text = "Deleted pages cannot be restored.",
        tone = MonarchTone.Danger,
    )
}

MonarchCalloutBlock(tone = MonarchTone.Info) {
    Text("Tip", style = MonarchTheme.typography.bodyStrong)
